challenge.starter:
const word = "radar";

// reversed ve isPalindrome

console.log(reversed, isPalindrome);

challenge.solution:
const word = "radar";

// reversed ve isPalindrome
const reversed = word.split("").reverse().join("");
const isPalindrome = word === reversed;

console.log(reversed, isPalindrome);

