project_task.solution:
const shipName = "Kartal";
let stars = 3;
let lives = 2;

// status'u şablon metinle oluştur
const status = `${shipName.toLocaleUpperCase("tr")} | Yıldız: ${stars}/10 | Can: ${lives}`;

console.log(status);

check.js:
const upper = shipName.toLocaleUpperCase("tr");
assert(status === `${upper} | Yıldız: ${stars}/10 | Can: ${lives}` || status === `${shipName.toUpperCase()} | Yıldız: ${stars}/10 | Can: ${lives}`, `status '${upper} | Yıldız: ${stars}/10 | Can: ${lives}' olmalı.`);
assert(_lines.includes(status), "status'u yazdırmalısın.");

